SELECT (SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-6c0a0dc9-c4a','sm-upload-66bdb06b-1cb','sm-upload-637470c0-5af','sm-upload-8b4e6e46-206','sm-upload-33959ca1-297','sm-upload-34c51de9-aa4','sm-upload-debc2a1c-66a','sm-upload-b33cfb39-448','sm-upload-89d8af71-0b6','sm-upload-95621150-291','sm-upload-64363012-149','sm-upload-6b506d3e-f76','sm-upload-a4de5316-99a','sm-upload-cc1e80b9-244','sm-upload-0112a6d9-283','sm-upload-2c6e632f-4ae','sm-upload-bba1a72e-f0c','sm-upload-d642ecae-43c','sm-upload-fa2c02f7-a2d','sm-upload-8ca7055e-888','sm-upload-6a381b8f-020','sm-upload-d11b6d58-141') AND album_id='pending-uploads') AS pending_wav_masters,(SELECT COUNT(*) FROM song_masters WHERE id IN ('1102','1101','1097','1098','1107','1100','1096','1105','1099','1106','1095','1103','2029','2025','2031','2024','2028','2027','2032','2030','2033','2026')) AS existing_flac_masters,(SELECT COUNT(*) FROM song_masters WHERE id IN ('2029','2025','2031','2024','2028','2027','2032','2030','2033','2026') AND track BETWEEN 1 AND 10) AS page_track_range,(SELECT COUNT(DISTINCT track) FROM song_masters WHERE id IN ('2029','2025','2031','2024','2028','2027','2032','2030','2033','2026')) AS page_distinct_tracks,(CASE WHEN EXISTS (SELECT 1 FROM albums WHERE id='al-9544935a62' AND name IS 'Fressia' AND sort_name IS 'fressia' AND year IS 2022 AND genre IS '未知流派' AND cover_r2_key IS 'covers/al-9544935a62' AND song_count=12 AND duration=0 AND size=397965617 AND compilation=0) AND EXISTS (SELECT 1 FROM albums WHERE id='al-7e5eae45c8' AND name IS '页间曲' AND sort_name IS '页间曲' AND year IS 2025 AND genre IS NULL AND cover_r2_key IS NULL AND song_count=1 AND duration=0 AND size=28058363 AND compilation=0) AND EXISTS (SELECT 1 FROM albums WHERE id='al-e9abb8fbe6' AND name IS '页间曲' AND sort_name IS '页间曲' AND year IS 2025 AND genre IS NULL AND cover_r2_key IS NULL AND song_count=1 AND duration=0 AND size=29797990 AND compilation=0) AND EXISTS (SELECT 1 FROM albums WHERE id='al-00d48fe122' AND name IS '页间曲' AND sort_name IS '页间曲' AND year IS 2025 AND genre IS NULL AND cover_r2_key IS NULL AND song_count=1 AND duration=0 AND size=10292617 AND compilation=0) AND EXISTS (SELECT 1 FROM albums WHERE id='al-1c10f4d14a' AND name IS '页间曲' AND sort_name IS '页间曲' AND year IS 2025 AND genre IS NULL AND cover_r2_key IS NULL AND song_count=1 AND duration=0 AND size=33962822 AND compilation=0) AND EXISTS (SELECT 1 FROM albums WHERE id='al-f88b0a5876' AND name IS '页间曲' AND sort_name IS '页间曲' AND year IS 2025 AND genre IS NULL AND cover_r2_key IS NULL AND song_count=1 AND duration=0 AND size=25172852 AND compilation=0) AND EXISTS (SELECT 1 FROM albums WHERE id='al-f249e24866' AND name IS '页间曲' AND sort_name IS '页间曲' AND year IS 2025 AND genre IS NULL AND cover_r2_key IS NULL AND song_count=1 AND duration=0 AND size=33112694 AND compilation=0) AND EXISTS (SELECT 1 FROM albums WHERE id='al-eb1cffa10c' AND name IS '页间曲' AND sort_name IS '页间曲' AND year IS 2025 AND genre IS NULL AND cover_r2_key IS NULL AND song_count=1 AND duration=0 AND size=28295489 AND compilation=0) AND EXISTS (SELECT 1 FROM albums WHERE id='al-4abb0b6368' AND name IS '页间曲' AND sort_name IS '页间曲' AND year IS 2025 AND genre IS NULL AND cover_r2_key IS NULL AND song_count=2 AND duration=0 AND size=67144451 AND compilation=0) AND EXISTS (SELECT 1 FROM albums WHERE id='al-8829e799ff' AND name IS '页间曲' AND sort_name IS '页间曲' AND year IS 2025 AND genre IS NULL AND cover_r2_key IS NULL AND song_count=1 AND duration=0 AND size=32699335 AND compilation=0) THEN 10 ELSE 0 END) AS source_album_metadata_matches,(SELECT COUNT(*) FROM albums WHERE id IN ('al-version-freesia-wav','al-version-pages-wav')) AS target_album_collisions,(SELECT COUNT(*) FROM album_display_groups WHERE id IN ('ag-version-freesia','ag-version-page-interlude')) AS target_group_collisions,(SELECT COUNT(*) FROM album_display_group_members WHERE album_id IN ('al-9544935a62','al-7e5eae45c8','al-e9abb8fbe6','al-00d48fe122','al-1c10f4d14a','al-f88b0a5876','al-f249e24866','al-eb1cffa10c','al-4abb0b6368','al-8829e799ff')) AS existing_group_memberships,(SELECT COUNT(*) FROM annotations WHERE item_type='album' AND item_id IN ('al-e9abb8fbe6','al-00d48fe122','al-1c10f4d14a','al-f88b0a5876','al-f249e24866','al-eb1cffa10c','al-4abb0b6368','al-8829e799ff')) AS fragment_annotations,(SELECT COUNT(*) FROM clone_id_map WHERE item_type='album' AND local_id IN ('al-e9abb8fbe6','al-00d48fe122','al-1c10f4d14a','al-f88b0a5876','al-f249e24866','al-eb1cffa10c','al-4abb0b6368','al-8829e799ff')) AS fragment_clone_mappings,(SELECT COUNT(*) FROM song_artists WHERE song_id IN ('sm-upload-6c0a0dc9-c4a','sm-upload-66bdb06b-1cb','sm-upload-637470c0-5af','sm-upload-8b4e6e46-206','sm-upload-33959ca1-297','sm-upload-34c51de9-aa4','sm-upload-debc2a1c-66a','sm-upload-b33cfb39-448','sm-upload-89d8af71-0b6','sm-upload-95621150-291','sm-upload-64363012-149','sm-upload-6b506d3e-f76','sm-upload-a4de5316-99a','sm-upload-cc1e80b9-244','sm-upload-0112a6d9-283','sm-upload-2c6e632f-4ae','sm-upload-bba1a72e-f0c','sm-upload-d642ecae-43c','sm-upload-fa2c02f7-a2d','sm-upload-8ca7055e-888','sm-upload-6a381b8f-020','sm-upload-d11b6d58-141')) AS wav_artist_credits,(SELECT COUNT(*) FROM song_artists WHERE song_id IN ('1102','1101','1097','1098','1107','1100','1096','1105','1099','1106','1095','1103','2029','2025','2031','2024','2028','2027','2032','2030','2033','2026')) AS flac_artist_credits;
